<?php
namespace App\Services;
use App\Models\PostCategory;
use Illuminate\Contracts\Pagination\LengthAwarePaginator;
use Illuminate\Support\Str;
class PostCategoryService { public function paginate(array $filters): LengthAwarePaginator { return PostCategory::with('parent')->when(filled($filters['search']??null),fn($q)=>$q->where('name','like','%'.trim($filters['search']).'%'))->orderBy('sort_order')->paginate((int)($filters['per_page']??20))->withQueryString(); } public function formContext(?PostCategory $category=null):array{return ['category'=>$category?:new PostCategory(['is_active'=>true]),'parents'=>PostCategory::whereNull('parent_id')->when($category,fn($q)=>$q->whereKeyNot($category->id))->orderBy('name')->get()];} public function create(array $data):PostCategory{return PostCategory::create($this->payload($data));} public function update(PostCategory $category,array $data):void{$category->update($this->payload($data));} public function delete(PostCategory $category):void{$category->delete();} private function payload(array $data):array{return ['parent_id'=>$data['parent_id']??null,'name'=>trim($data['name']),'slug'=>$data['slug']?:Str::slug($data['name']),'description'=>$data['description']??null,'seo_title'=>$data['seo_title']??null,'seo_description'=>$data['seo_description']??null,'sort_order'=>(int)($data['sort_order']??0),'is_active'=>(bool)($data['is_active']??false)];} }
